--- ReplicatedStorage.Controllers.UIController.spec [ModuleScript]
-- y u r i

local var1 = require(script.Parent.UIControllerReadiness)
return function()
	describe("UIController readiness barrier", function()
		it("becomes ready only after every required window is ready", function()
			local var2 = var1.new({ "HUD", "Store" })
			var2:RegisterWindow("HUD")
			var2:RegisterWindow("Store")
			local str1 = "Store"
			expect(var2:MarkWindowReady(str1)).to.equal(false)
			str1 = "Store"
			expect(var2:MarkWindowReady(str1)).to.equal(false)
			expect(var2:IsReady()).to.equal(false)
			expect(var2:GetMissingRequired()[1]).to.equal("HUD")
			str1 = "HUD"
			expect(var2:MarkWindowReady(str1)).to.equal(true)
			expect(var2:IsReady()).to.equal(true)
		end)

		it("keeps contextual windows blocked until their own marker", function()
			local var2 = var1.new({ "HUD" })
			var2:RegisterWindow("HUD")
			var2:RegisterWindow("Dialogue")
			var2:MarkWindowReady("HUD")
			local str1 = "Dialogue"
			expect(var2:CanOpen(str1)).to.equal(false)
			var2:MarkWindowReady("Dialogue")
			str1 = "Dialogue"
			expect(var2:CanOpen(str1)).to.equal(true)
		end)

		it("rejects a marker for an unregistered window", function()
			local var2 = var1.new({ "HUD" })
			expect((pcall(function()
				var2:MarkWindowReady("HUD")
			end))).to.equal(false)
		end)

		it("fails terminally and reports sorted missing windows", function()
			local var2 = var1.new({ "Store", "HUD", "Backpack" })
			var2:RegisterWindow("Store")
			var2:RegisterWindow("HUD")
			var2:RegisterWindow("Backpack")
			var2:MarkWindowReady("HUD")
			expect(var2:Fail()).to.equal(true)
			expect(var2:Fail()).to.equal(false)
			expect(var2:IsReady()).to.equal(false)
			local var3 = var2:GetMissingRequired()
			expect(#var3).to.equal(2)
			expect(var3[1]).to.equal("Backpack")
			expect(var3[2]).to.equal("Store")
		end)

		it("keeps readiness one-shot when startup windows register again", function()
			local var2 = var1.new({ "HUD" })
			var2:RegisterWindow("HUD")
			local str1 = "HUD"
			expect(var2:MarkWindowReady(str1)).to.equal(true)
			var2:RegisterWindow("HUD")
			str1 = "HUD"
			expect(var2:MarkWindowReady(str1)).to.equal(false)
			expect(var2:Fail()).to.equal(false)
			expect(var2:IsReady()).to.equal(true)
		end)
	end)
