--- ReplicatedStorage.Data.Catalog.Boss.spec [ModuleScript]
-- y u r i

return function()
	local var1 = game:GetService("ReplicatedStorage")
	local var2 = require(var1.Data.Catalog)
	local var3 = require(var1.Data.Catalog.Event)
	local var4 = require(var1.Data.Config.AuraGachaConfig)
	describe("Boss catalog", function()
		it("points every pool entry at a real Fish.Boss id", function()
			for k1, v1 in var2.Boss.GetWeatherIds() do
				local var1 = v1
				for k2, v2 in var2.Boss.GetPool(var1) do
					local var3 = var2.Fish.GetById(v2.id)
					expect(var3).never.to.equal(nil)
					if not var3 then
						continue
					end

					expect(var3.kind).to.equal("Boss")
				end
			end
		end)

		it("gives every boss fish the Divine rarity", function()
			for k1, v1 in var2.Fish.GetAll() do
				if v1.kind ~= "Boss" then
					continue
				end

				expect(v1.rarity).to.equal("Divine")
			end
		end)

		it("keys every pool on a real Weather event source", function()
			for k1, v1 in var2.Boss.GetWeatherIds() do
				local var1 = var3.source[v1]
				expect(var1).never.to.equal(nil)
				if not var1 then
					continue
				end

				expect(var1.category).to.equal("Weather")
			end
		end)

		it("places each boss id in at most one weather's pool", function()
			local tbl1 = {}
			for k1, v1 in var2.Boss.GetWeatherIds() do
				local var1 = v1
				for k2, v2 in var2.Boss.GetPool(var1) do
					expect(tbl1[v2.id]).to.equal(nil)
					tbl1[v2.id] = v1
				end
			end
		end)

		it("sums to a positive total weight in every pool", function()
			for k1, v1 in var2.Boss.GetWeatherIds() do
				local var1 = v1
				local num1 = 0
				for k2, v2 in var2.Boss.GetPool(var1) do
					num1 = num1 + v2.weight
				end

				expect(0 < num1).to.equal(true)
			end
		end)

		it("resolves GetWeatherForBoss back to the pool that holds the boss", function()
			for k1, v1 in var2.Boss.GetWeatherIds() do
				local var1 = v1
				for k2, v2 in var2.Boss.GetPool(var1) do
					local var3 = v2.id
					expect(var2.Boss.GetWeatherForBoss(var3)).to.equal(v1)
				end
			end
		end)

		it("weights every boss aura reward onto a non-empty gacha rarity pool", function()
			for k1, v1 in var2.Fish.GetAll() do
				local var1 = v1.boss
				var1 = var1 and v1.boss.reward
				if not var1 then
					continue
				end

				local num1 = 0
				for k2, v2 in var1.auraRarityWeights, nil do
					expect(0 < v2).to.equal(true)
					local var5 = var4.GetPool(k2)
					local var6 = expect
					local bool1 = false
					if var5 ~= nil then
						bool1 = 0 < (#var5)
					end

					var6 = var6(bool1).to.equal
					var6(true)
					num1 = num1 + v2
				end

				expect(0 < num1).to.equal(true)
			end
		end)

		it("returns nil for a weather outside the boss pools", function()
			local str1 = "weather_rain"
			expect(var2.Boss.GetPool(str1)).to.equal(nil)
			str1 = "not_a_boss"
			expect(var2.Boss.GetWeatherForBoss(str1)).to.equal(nil)
		end)
	end)
end

