--- ReplicatedStorage.Data.Catalog.DailyRewards.spec [ModuleScript]
-- y u r i

return function()
	local var1 = require(script.Parent.DailyRewards)
	local tbl1 = { Coin = true, Gem = true, Exp = true, Item = true, Rod = true }
	local var2 = require(game:GetService("ReplicatedStorage").Data.Catalog)
	describe("DailyRewards catalog", function()
		it("has exactly a 7-day cycle", function()
			expect(#var1.GetAll()).to.equal(7)
		end)

		it("days are 1..7, contiguous, unique and in order", function()
			for k1, v1 in ipairs((var1.GetAll())) do
				expect(v1.Day).to.equal(k1)
			end
		end)

		it("GetByDay round-trips 1..7 and rejects out-of-range", function()
			for i1 = 1, 7 do
				local var2 = var1.GetByDay(i1)
				expect(var2).to.be.ok()
				expect(var2.Day).to.equal(i1)
			end

			local num1 = 0
			expect(var1.GetByDay(num1)).to.equal(nil)
			num1 = 8
			expect(var1.GetByDay(num1)).to.equal(nil)
		end)

		it("grants the configured Coin and Gem pair for each day", function()
			local tbl1 = { 40000, 40, "40,000 Coins + 40 Gems" }
			local tbl2 = { 50000, 50, "50,000 Coins + 50 Gems" }
			local tbl3 = {
				{ 10000, 10, "10,000 Coins + 10 Gems" },
				{ 20000, 20, "20,000 Coins + 20 Gems" },
				{ 30000, 30, "30,000 Coins + 30 Gems" },
				tbl1,
				tbl2,
				{ 70000, 70, "70,000 Coins + 70 Gems" },
				{ 100000, 100, "100,000 Coins + 100 Gems" },
			}

			for k1, v1 in var1.GetAll() do
				expect(#v1.Rewards).to.equal(2)
				expect(v1.Rewards[1].Kind).to.equal("Coin")
				expect(v1.Rewards[1].Amount).to.equal(tbl3[k1][1])
				expect(v1.Rewards[2].Kind).to.equal("Gem")
				expect(v1.Rewards[2].Amount).to.equal(tbl3[k1][2])
				expect(v1.DisplayName).to.equal(tbl3[k1][3])
			end
		end)

		it("every reward component has a valid kind and positive amount", function()
			for k1, v1 in var1.GetAll() do
				for k2, v2 in v1.Rewards, nil do
					expect(tbl1[v2.Kind]).to.equal(true)
					expect(0 < v2.Amount).to.equal(true)
				end
			end
		end)

		it("every reward has tooltip copy", function()
			for k1, v1 in var1.GetAll() do
				expect((type(v1.DisplayName))).to.equal("string")
				expect(0 < (#v1.DisplayName)).to.equal(true)
				expect((type(v1.Description))).to.equal("string")
				expect(0 < (#v1.Description)).to.equal(true)
			end
		end)

		it("Item and Rod rewards reference real catalog ids", function()
			for k1, v1 in var1.GetAll() do
				for k2, v2 in v1.Rewards, nil do
					if v2.Kind == "Rod" then
						expect(v2.ItemId).to.be.ok()
						local var3 = v2.ItemId
						expect(var2.Rod.GetById(var3)).to.be.ok()
					else
						if v2.Kind ~= "Item" then
							continue
						end

						expect(v2.ItemId).to.be.ok()
						local var4 = v2.ItemId
						expect(var2.Bait.GetById(var4)).to.be.ok()
					end
				end
			end
		end)
	end)
end

--- ReplicatedStorage.Data.Catalog.Island.spec [ModuleScript]
-- y u r i

return function()
	local var1 = game:GetService("ReplicatedStorage")
	local var2 = require(var1.Data.Catalog)
	describe("Island catalog order", function()
		it("orders are 1..N, contiguous and unique (GetAll sorts by order)", function()
			for k1, v1 in ipairs((var2.Island.GetAll())) do
				expect(v1.order).to.equal(k1)
			end
		end)

		it("every fish reference is real with a positive weight", function()
			for k1, v1 in var2.Island.GetAll() do
				for k2, v2 in v1.fishes, nil do
					local var1 = v2.fishId
					expect(var2.Fish.GetById(var1)).to.be.ok()
					expect(0 < v2.weight).to.equal(true)
				end
			end
		end)

		it("owns a non-empty icon for every island", function()
			for k1, v1 in var2.Island.GetAll() do
				expect(v1.icon ~= "").to.equal(true)
			end
		end)
	end)

	local var3 = require(var1.Data.Config.IslandConfig)
	describe("Island catalog <-> IslandConfig parity", function()
		it("every catalog island has a config entry", function()
			for k1, v1 in var2.Island.GetAll() do
				expect(var3[v1.id]).to.be.ok()
			end
		end)

		it("every config island exists in the catalog", function()
			for k1 in var3, nil do
				local var1 = k1
				expect(var2.Island.GetById(var1)).to.be.ok()
			end
		end)

		it("starter island is default-unlocked and free", function()
			local var1 = var3.island_starter
			expect(var1).to.be.ok()
			expect(var1.defaultUnlocked).to.equal(true)
			expect(var1.unlockCost).to.equal(0)
		end)
	end)
end

--- ReplicatedStorage.Data.Catalog.Skill.spec [ModuleScript]
-- y u r i

return function()
	local var1 = game:GetService("ReplicatedStorage")
	local var2 = require(var1.Data.Catalog)
	local var3 = require(var1.Data.Enums.RarityEnums)
	local var4 = require(var1.Data.Config.FishingConfig)
	describe("Skill catalog", function()
		it("owns valid display metadata for every skill", function()
			for k1, v1 in var2.Skill.GetAll() do
				local var1 = v1.id
				expect(var2.Skill.GetById(var1)).to.equal(v1)
				expect(v1.icon ~= "").to.equal(true)
				expect(var3.Rarity[v1.rarity]).to.equal(v1.rarity)
			end
		end)

		it("partitions skills by their catalog rarity", function()
			local num1 = 0
			local tbl1 = {}
			for k1, v1 in var2.Skill.GetAll() do
				tbl1[v1.id] = true
			end

			for k2, v2 in var3.Order, nil do
				for k3, v3 in var2.Skill.GetByRarity(v2) do
					expect(v3.rarity).to.equal(v2)
					expect(tbl1[v3.id]).to.equal(true)
					tbl1[v3.id] = nil
					num1 = num1 + 1
				end
			end

			expect(num1).to.equal(#var2.Skill.GetAll())
			local var1 = tbl1
			expect(next(var1)).to.equal(nil)
		end)

		it("returns an empty pool for an unknown rarity", function()
			expect(#var2.Skill.GetByRarity("Unknown")).to.equal(0)
		end)

		it("defines a non-empty strictly increasing hit timeline for every damaging skill", function()
			for k1, v1 in var2.Skill.GetAll() do
				if not var4.Skill.Kinds[v1.kind].dealsDamage then
					continue
				end

				expect(0 < (#v1.hitTimes)).to.equal(true)
				expect(0 < v1.damageCoef).to.equal(true)
				local num1 = -math.huge
				for k2, v2 in v1.hitTimes, nil do
					expect(num1 < v2).to.equal(true)
					local var1 = v2
				end
			end
		end)

		it("gives a non-damaging skill no hits, no damage and a known effect", function()
			for k1, v1 in var2.Skill.GetAll() do
