				if not var1 then
					continue
				end

				expect(var4.Skill.Effects[var1.type] ~= nil).to.equal(true)
			end
		end)

		it("covers the whole hit timeline with castTime", function()
			for k1, v1 in var2.Skill.GetAll() do
				expect((v1.hitTimes[#v1.hitTimes] or 0) <= v1.castTime).to.equal(true)
			end
		end)

		it("gives every skill in a rarity the same cast-to-cast cycle", function()
			local tbl1 = {}
			for k1, v1 in var2.Skill.GetAll() do
				expect(1.5 <= v1.cooldown).to.equal(true)
				local var4 = tbl1[v1.rarity]
				local var5 = v1.castTime + v1.cooldown
				if var4 then
					local var6 = expect
					local bool1 = true
					if math.abs(var5 - var4) >= 1e-06 then
						bool1 = v1.cooldown == 1.5
					end

					var6 = var6(bool1).to.equal
					var6(true)
				else
					tbl1[v1.rarity] = var5
				end
			end
		end)
	end)
