--- ReplicatedStorage.Data.Catalog.Unit.spec [ModuleScript]
-- y u r i

local var1 = require(script.Parent)
local var2 = require(script.Parent.Unit)
local var3 = require(game:GetService("ReplicatedStorage").Shared.Units.UnitConfig)
return function()
	describe("Catalog.Unit", function()
		it("exposes the authored leaf entry through GetById", function()
			local str1 = "ba_chang"
			expect(var1.Unit.GetById(str1)).to.equal(var2.ba_chang)
			str1 = "missing"
			expect(var1.Unit.GetById(str1)).to.equal(nil)
		end)

		it("lists exactly 16 entries in stable ID order without exposing its backing map", function()
			local var3 = var1.Unit.GetAll()
			expect(#var3).to.equal(16)
			for k1, v1 in var3, nil do
				expect(var2[v1.id]).to.equal(v1)
				if 1 >= k1 then
					continue
				end

				expect(var3[k1 - 1].id < v1.id).to.equal(true)
			end

			table.remove(var3)
			expect(#var1.Unit.GetAll()).to.equal(16)
		end)

		it("keeps rarity / buff balance separate and removes the retired test definition", function()
			expect(var3.Definitions).to.equal(nil)
			local str1 = "test_unit"
			expect(var1.Unit.GetById(str1)).to.equal(nil)
			for k1, v1 in var1.Unit.GetAll() do
				expect(v1.modelName).to.equal(v1.name)
				expect(v1.rodId).to.equal("wooden_rod")
				expect(v1.rodSkinId).to.equal("None")
				expect(v1.rarity).to.equal(nil)
			end
		end)
	end)
end

