--- ReplicatedStorage.Data.Config.FishingConfig.TensionModel.spec [ModuleScript]
-- y u r i

local var1 = game:GetService("ReplicatedStorage")
local var2 = require(var1.Data.Config.FishingConfig)
local var3 = require(var1.Data.Catalog)
return function()
	local var1 = var2.Combat.Levels
	describe("click can never lower tension", function()
		it("keeps the click multiplier strictly positive and below one", function()
			expect(0 < var2.Tension.ClickSlowMult).to.equal(true)
			expect(var2.Tension.ClickSlowMult < 1).to.equal(true)
		end)

		for k1, v1 in var1, nil do
			it(("stays positive while clicking on %*"):format(k1), function()
				expect(0 < v1.growPerSec * var2.Tension.ClickSlowMult - 0).to.equal(true)
			end)

		end
	end)

	describe("accuracy is the gate, skills are a bonus", function()
		for k1, v1 in var1, nil do
			it(("holds tension down on %* for a player who never misses and never casts"):format(k1), function()
				local var1 = v1
				local var3 = var1.growPerSec * var2.Tension.ClickSlowMult - 0 - var1.counterReduce / ((var1.counterFreq.min + var1.counterFreq.max) * 0.5) * 1 + var1.missMag / ((var1.counterFreq.min + var1.counterFreq.max) * 0.5) * 0
				expect(var3 < 0).to.equal(true)
			end)

			it(("loses on %* for a sloppy player even with a full skill rotation"):format(k1), function()
				local var1 = v1
				local var3 = var1.growPerSec * var2.Tension.ClickSlowMult - var2.Skill.DrainPerUptime - var1.counterReduce / ((var1.counterFreq.min + var1.counterFreq.max) * 0.5) * 0.5 + var1.missMag / ((var1.counterFreq.min + var1.counterFreq.max) * 0.5) * 0.5
				expect(0 < var3).to.equal(true)
			end)

			it(("lowers the accuracy %* demands when skills are cast"):format(k1), function()
				local var1 = v1
