local var1 = require(game:GetService("ReplicatedStorage").Data.Config.FishingConfig)
local function SimulateKill(arg1, arg2, arg3)
	local var2 = var1.Boss
	local var3 = var2.Phase1HpFraction
	local var4 = (var2.Phase1HpFraction + var2.Phase2HpFraction) / arg1
	local num1 = 1
	local var5 = var3
	local num2 = 0
	local var6 = var2.HealFirstDelayP1
	local var7 = var2.HealFirstDelayP2
	while true do
		if num2 >= 3600 then
			break
		end

		var5 = var5 - var4 * 0.25
		num2 = num2 + 0.25
		if var5 <= 0 then
			if 2 <= num1 then
				return num2
			end

			var3 = var2.Phase2HpFraction
			num2 = num2 + var2.PhaseIntermissionSec
			num1 = 2
			var5 = var3
			var6 = num2 + var2.HealFirstDelayP2
			var7 = var2.HealFirstDelayP2
		end

		if 0 >= var6 or var6 > num2 then
			continue
		end

		if 2 <= num1 then
			var7 = var7 + var2.HealCooldownStepSec
		else
			local var8 = num2 + var7
		end

		local var9 = math.min(var3, var5 + math.min((var3 - var5) * arg2, var3 * arg3))
		var8 = 0
	end

	return nil
end

return function()
	local var2 = var1.Boss
	describe("heal amount", function()
		it("is zero at full health and grows as the boss loses HP", function()
			expect((math.min(var2.HealMissingPct * 0, var2.HealCapPct * 1))).to.equal(0)
			expect(math.min(var2.HealMissingPct * 0.25, var2.HealCapPct * 1) < math.min(var2.HealMissingPct * 0.5, var2.HealCapPct * 1)).to.equal(true)
		end)

		it("never exceeds the cap even at one HP left", function()
			expect((math.min(var2.HealMissingPct * 1, var2.HealCapPct * 1))).to.equal(var2.HealCapPct)
		end)
	end)

	describe("the fight always converges", function()
		local num1 = 450
		for k1, v1 in { 270, num1, 600, 900 }, nil do
			it(("kills at a %*s base time-to-kill"):format(v1), function()
				expect((SimulateKill(v1, var2.HealMissingPct, var2.HealCapPct))).to.be.ok()
			end)

		end

		it("stretches a strong player's fight without doubling it", function()
			local var1 = SimulateKill(270, var2.HealMissingPct, var2.HealCapPct)
			expect(var1).to.be.ok()
			expect(270 < var1).to.equal(true)
			expect(var1 < 540).to.equal(true)
		end)

		it("costs a weak player proportionally more time than a strong one", function()
			expect(SimulateKill(270, var2.HealMissingPct, var2.HealCapPct) / 270 < SimulateKill(600, var2.HealMissingPct, var2.HealCapPct) / 600).to.equal(true)
		end)
	end)

	describe("the growing cooldown is what rules out an unkillable boss", function()
		it("walls when the heal gap never grows", function()
			expect(((function(arg1)
				local num1 = 1
				local num2 = 0
				local var1 = var2.HealFirstDelayP2
				while true do
					if num2 >= 3600 then
						break
					end

					local var3 = 1 / arg1
					num1 = num1 - var3 * 0.25
					num2 = num2 + 0.25
					if num1 <= 0 then
						return num2
					end

					if var1 > num2 then
						continue
					end

					local var4 = math.min(1, num1 + math.min((1 - num1) * var2.HealMissingPct, var2.HealCapPct * 1))
					local var5 = num2 + var2.HealFirstDelayP2
				end

				return nil
			end)(600))).to.equal(nil)
		end)
	end)

	describe("the cap keeps the fight watchable", function()
		it("cuts a meaningful slice off an uncapped fight at every DPS level", function()
			local num1 = 450
			for k1, v1 in { 270, num1, 600 }, nil do
				expect(SimulateKill(v1, var2.HealMissingPct, var2.HealCapPct) < SimulateKill(v1, 0.25, 1)).to.equal(true)
			end
		end)
	end)
end

