--- ReplicatedStorage.Data.Config.SkillGachaConfig.spec [ModuleScript]
-- y u r i

return function()
	local var1 = game:GetService("ReplicatedStorage")
	local var2 = require(script.Parent.SkillGachaConfig)
	local var3 = require(var1.Data.Enums.RarityEnums)
	local var4 = require(var1.Data.Catalog)
	describe("SkillGachaConfig policy", function()
		it("uses positive odds for real rarities with non-empty skill pools", function()
			local num1 = 0
			for k1, v1 in var2.RarityOdds, nil do
				expect(var3.Rarity[k1]).to.equal(k1)
				expect(0 < v1).to.equal(true)
				expect(0 < (#var4.Skill.GetByRarity(k1))).to.equal(true)
				num1 = num1 + v1
			end

			expect(num1).to.equal(100)
		end)

		it("defines the approved Coin prices", function()
			expect(var2.Coin.BaseCost).to.equal(20000)
			expect(var2.Coin.IncrementPerPull).to.equal(5000)
			expect(var2.Coin.ResetSeconds).to.equal(43200)
		end)

		it("defines ordered independent pity guarantees", function()
			local num1 = math.huge
			for k1, v1 in var2.PityTiers, nil do
				expect(0 < v1.threshold).to.equal(true)
				expect(var3.Rarity[v1.rarity]).to.equal(v1.rarity)
				expect(0 < (#var4.Skill.GetByRarity(v1.rarity))).to.equal(true)
				local var1 = table.find(var3.Order, v1.rarity) or 0
				expect(var1 < num1).to.equal(true)
				local var5 = var1
			end

			expect(var2.PityTiers[1].rarity).to.equal("Mythical")
			expect(var2.PityTiers[1].threshold).to.equal(500)
			expect(var2.PityTiers[2].rarity).to.equal("Legendary")
			expect(var2.PityTiers[2].threshold).to.equal(50)
		end)

		it("defines valid pools with positive weights matching catalog rarities", function()
			for k1 in var2.RarityOdds, nil do
				local var1 = var2.GetPool(k1)
				expect(var1).to.be.ok()
				expect(0 < (#var1)).to.equal(true)
				local var3 = var2.GetPoolTotalWeight(k1)
				expect(var3).to.be.ok()
				expect(0 < var3).to.equal(true)
				local num1 = 0
				for k2, v1 in var1, nil do
					expect(0 < v1.weight).to.equal(true)
					expect(0 < v1.rate).to.equal(true)
					expect(v1.item).to.be.ok()
					expect(v1.item.rarity).to.equal(k1)
					num1 = num1 + v1.weight
				end

				expect(num1).to.equal(var3)
			end
		end)

		it("includes Uncommon in odds and pools", function()
			expect(var2.RarityOdds.Uncommon).to.be.ok()
			expect(0 < var2.RarityOdds.Uncommon).to.equal(true)
			local var1 = var2.GetPool("Uncommon")
			expect(var1).to.be.ok()
			expect(0 < (#var1)).to.equal(true)
		end)

		it("only includes catalog skills and excludes quest-only rewards", function()
			local tbl1 = {}
			for k1, v1 in var2.Pools, nil do
				for k2, v2 in v1, nil do
					tbl1[v2.id] = true
					local var1 = v2.id
					expect(var4.Skill.GetById(var1)).to.be.ok()
				end
			end

			expect(tbl1.taiji_hooking_art_v2).to.equal(nil)
		end)
	end)
end

--- ReplicatedStorage.Data.Config.RodShopConfig.spec [ModuleScript]
-- y u r i

return function()
	local var1 = require(script.Parent.RodShopConfig)
	local var2 = require(game:GetService("ReplicatedStorage").Data.Catalog)
	describe("RodShopConfig entries", function()
		it("every entry has a sane price, currency and island", function()
			for k1, v1 in var1, nil do
				expect((type(v1.price))).to.equal("number")
				expect(0 <= v1.price).to.equal(true)
