	Weights = {
		weather_rain = 0,
		weather_blood_moon = 14,
		weather_thunderstorm = 5,
		weather_snowfall = 30,
		weather_void_storm = 1,
		weather_rainbow_rain = 50,
	},
})

local tbl2 = { TEST_MODE = false, DEFAULT_WEIGHT = 100, PRESET = table.freeze(tbl1) }
tbl2.Active = if tbl2.TEST_MODE then tbl2.PRESET.Test else tbl2.PRESET.Release
tbl2.GetWeight = function(arg1)
	local var1 = tbl2.Active.Weights[arg1]
	return var1 or tbl2.DEFAULT_WEIGHT
end

tbl2.ThunderstormStrikeAudio = table.freeze({
	MinDistance = 8,
	MaxDistance = 85,
	CutoffDistance = 120,
	MinVolumeFactor = 0.2,
	MaxVolumeFactor = 1,
})

tbl2.CalculateThunderstormStrikeVolume = function(arg1, arg2)
	local var1 = tbl2.ThunderstormStrikeAudio
	if var1.CutoffDistance < arg2 then
		return 0
	end

	if arg2 <= var1.MinDistance then
		return arg1 * var1.MaxVolumeFactor
	end

	if var1.MaxDistance <= arg2 then
		return arg1 * var1.MinVolumeFactor * (1 - (arg2 - var1.MaxDistance) / (var1.CutoffDistance - var1.MaxDistance))
	end

	local var2 = (arg2 - var1.MinDistance) / (var1.MaxDistance - var1.MinDistance)
	return arg1 * (var1.MinVolumeFactor + (var1.MaxVolumeFactor - var1.MinVolumeFactor) * ((1 - var2) * (1 - var2)))
end

return tbl2

--- ReplicatedStorage.Data.Config.AuraInnateConfig.spec [ModuleScript]
