return function()
	local var1 = require(script.Parent.AuraInnateConfig)
	describe("AuraInnateConfig", function()
		it("owns the conditions and effects CombatPassives evaluates", function()
			local var2 = var1.GetById("execute_below_hp")
			expect(var2.condition.kind).to.equal("TargetHpBelow")
			expect(var2.condition.threshold).to.equal(0.05)
			expect(var2.effect).to.equal("Execute")
			local var3 = var1.GetById("low_hp_bonus_dmg")
			expect(var3.condition.kind).to.equal("TargetHpBelow")
			expect(var3.condition.threshold).to.equal(0.5)
			expect(var3.effect).to.equal("SkillDamagePct")
			local var4 = var1.GetById("combo_5_skill_bonus")
			expect(var4.condition.kind).to.equal("CastCycle")
			expect(var4.condition.charge).to.equal(5)
			expect(var4.effect).to.equal("SkillDamagePct")
		end)

		it("keeps skillDamagePct out of the stat rolls only when an innate needs a magnitude", function()
			local tbl1 = {
				{ stat = "skillDamagePct", op = "add", value = 0.15 },
				{ stat = "luck", op = "add", value = 4 },
				{ stat = "skillDamagePct", op = "add", value = 0.05 },
			}

			local var2, var3 = var1.SplitRolls({ "low_hp_bonus_dmg" }, tbl1)
			expect(#var2).to.equal(1)
			expect(var2[1].stat).to.equal("luck")
			expect(math.abs(var3 - 0.2) < 1e-09).to.equal(true)
			local var4, var5 = var1.SplitRolls({ "execute_below_hp" }, tbl1)
			expect(var4).to.equal(tbl1)
			expect(var5).to.equal(0)
			expect((var1.SplitRolls(nil, tbl1))).to.equal(tbl1)
		end)

		it("owns exact Viewer copy and semantic icons", function()
			local var2 = var1.GetById("execute_below_hp")
			expect(var2.description).to.equal("Execute: Kill enemies instantly below {condition}.")
			expect(var2.icon).to.equal("rbxassetid://114890784764877")
			local var3 = var1.GetById("low_hp_bonus_dmg")
			expect(var3.description).to.equal("Bleeding: Deal {bonus} to enemies below {condition}.")
			expect(var3.icon).to.equal("rbxassetid://95693686365777")
			local var4 = var1.GetById("combo_5_skill_bonus")
			expect(var4.description).to.equal("Resonance: Every {condition}, the next cast deals {bonus}.")
			expect(var4.icon).to.equal("rbxassetid://134871723932904")
		end)

		it("rejects unknown innate ids", function()
			local str1 = "missing"
			expect(var1.GetById(str1)).to.equal(nil)
		end)
	end)
end

