require(game:GetService("ReplicatedStorage").Data.Types)
local var1 = require(game:GetService("ReplicatedFirst").manual_assets)
local tbl1 = { execute_below_hp = table.freeze({
	id = "execute_below_hp",
	name = "Execute",
	description = "Execute: Kill enemies instantly below {condition}.",
	icon = var1["Image/Icon/Innate/execute_below_hp.png"],
	condition = table.freeze({ kind = "TargetHpBelow", threshold = 0.05 }),
	effect = "Execute",
}) }

tbl1.low_hp_bonus_dmg = table.freeze({
	id = "low_hp_bonus_dmg",
	name = "Bleeding",
	description = "Bleeding: Deal {bonus} to enemies below {condition}.",
	icon = var1["Image/Icon/Innate/low_hp_bonus_dmg.png"],
	condition = table.freeze({ kind = "TargetHpBelow", threshold = 0.5 }),
	effect = "SkillDamagePct",
})

tbl1.combo_5_skill_bonus = table.freeze({
	id = "combo_5_skill_bonus",
	name = "Resonance",
	description = "Resonance: Every {condition}, the next cast deals {bonus}.",
	icon = var1["Image/Icon/Innate/combo_5_skill_bonus.png"],
	condition = table.freeze({ kind = "CastCycle", charge = 5 }),
	effect = "SkillDamagePct",
})

local tbl2 = {
	GetById = function(arg1)
		return tbl1[arg1]
	end,
	GetAll = function()
		return tbl1
	end,
	NeedsMagnitude = function(arg1)
		if not arg1 then
			return false
		end

		for k1, v1 in arg1, nil do
			local var1 = tbl1[v1]
			if not var1 then
				continue
			end

			if var1.effect ~= "SkillDamagePct" then
				continue
			end

			return true
		end

		return false
	end,
}

tbl2.SplitRolls = function(arg1, arg2)
	if not tbl2.NeedsMagnitude(arg1) then
		return arg2, 0
	end

	local tbl1 = {}
	local num1 = 0
	for k1, v1 in arg2, nil do
		if v1.stat == "skillDamagePct" then
			num1 = num1 + v1.value
		else
			table.insert(tbl1, v1)
		end
	end

	return tbl1, num1
end

local var2 = tbl2
return table.freeze(var2)

