--- ReplicatedStorage.Data.Config.WeatherConfig.spec [ModuleScript]
-- y u r i

local var1 = require(game:GetService("ReplicatedStorage").Data.Config.WeatherConfig)
return function()
	describe("WeatherConfig.ThunderstormStrikeAudio", function()
		it("provides a valid configuration for thunderstorm lightning strike audio", function()
			local var2 = var1.ThunderstormStrikeAudio
			expect(var2).never.to.equal(nil)
			expect(var2.MinDistance).to.equal(8)
			expect(var2.MaxDistance).to.equal(85)
			expect(var2.CutoffDistance).to.equal(120)
			expect(var2.MinVolumeFactor).to.equal(0.2)
			expect(var2.MaxVolumeFactor).to.equal(1)
		end)
	end)

	describe("WeatherConfig.CalculateThunderstormStrikeVolume", function()
		it("returns baseVolume * MaxVolumeFactor when distance is less than or equal to MinDistance", function()
			local num1 = 0.5
			local num2 = 0
			local var2 = expect(var1.CalculateThunderstormStrikeVolume(num1, num2)).to.equal
			local var3 = var1.ThunderstormStrikeAudio
			var2(0.5 * var3.MaxVolumeFactor)
			num1 = 0.5
			num2 = var3.MinDistance
			var2 = expect(var1.CalculateThunderstormStrikeVolume(num1, num2)).to.equal
			var2(0.5 * var3.MaxVolumeFactor)
		end)

		it("returns 0 when distance is greater than CutoffDistance", function()
			local num1 = 0.5
			local var2 = var1.ThunderstormStrikeAudio.CutoffDistance + 1
			expect(var1.CalculateThunderstormStrikeVolume(num1, var2)).to.equal(0)
		end)

		it("returns baseVolume * MinVolumeFactor at MaxDistance", function()
			local var2 = var1.ThunderstormStrikeAudio
			expect(math.abs(var1.CalculateThunderstormStrikeVolume(0.5, var2.MaxDistance) - 0.5 * var2.MinVolumeFactor) < 0.0001).to.equal(true)
		end)

		it("smoothly scales volume between MinDistance and MaxDistance", function()
			local var2 = var1.ThunderstormStrikeAudio
			local var3 = var1.CalculateThunderstormStrikeVolume(0.5, (var2.MinDistance + var2.MaxDistance) / 2)
			expect(0.5 * var2.MinVolumeFactor < var3).to.equal(true)
			expect(var3 < 0.5 * var2.MaxVolumeFactor).to.equal(true)
		end)
	end)
end

