	X2BossDrops = "x2_boss_drops",
	X2FishInventory = "x2_fish_inventory",
	X3FishInventory = "x3_fish_inventory",
	X2SkillBookStack = "x2_skill_book_stack",
	X3SkillBookStack = "x3_skill_book_stack",
	Multipliers = table.freeze({ x2_money = 2, x2_player_exp = 2, x2_mastery = 2 }),
}

tbl1.StorageBonus = table.freeze({ x2_fish_inventory = 50, x3_fish_inventory = 100 })
tbl1.BookStackBonus = table.freeze({ x2_skill_book_stack = 5, x3_skill_book_stack = 10 })
tbl1.Has = function(arg1, arg2)
	local var1 = arg1.Entitlements
	local bool1 = false
	if type(var1) == "table" then
		bool1 = var1[arg2] == true
	end

	return bool1
end

tbl1.Scale = function(arg1, arg2, arg3)
	if not tbl1.Has(arg1, arg2) then
		return arg3
	end

	return arg3 * (tbl1.Multipliers[arg2] or 1)
end

tbl1.FishCapacity = function(arg1)
	local num1 = 0
	for k1, v1 in tbl1.StorageBonus, nil do
		if not tbl1.Has(arg1, k1) then
			continue
		end

		num1 = num1 + v1
	end

	return var2.FishStorage.BaseCapacity + num1
end

tbl1.BookStackCap = function(arg1)
