			continue
		end

		num1 = num1 + v1
	end

	local var1 = arg1.SkillGacha
	var1 = var1 and arg1.SkillGacha.StorageBonus
	if type(var1) == "number" and 0 < var1 then
		num1 = num1 + math.floor(var1)
