--- ReplicatedStorage.Data.Config.EntitlementConfig.spec [ModuleScript]
-- y u r i

return function()
	local var1 = require(script.Parent.EntitlementConfig)
	local function withKeys(...)
		local tbl1 = {}
		for k1, v1 in { ... }, nil do
			tbl1[v1] = true
		end

		return { Entitlements = tbl1 }
	end

	local var2 = require(script.Parent.PlayerConfig)
	describe("EntitlementConfig", function()
		it("leaves an amount alone without the key", function()
			local var2 = withKeys()
			local var3 = var1.X2Money
			local num1 = 250
			expect(var1.Scale(var2, var3, num1)).to.equal(250)
		end)

		it("doubles an amount with the key", function()
			local var2 = withKeys(var1.X2Money)
			local var3 = var1.X2Money
			local num1 = 250
			expect(var1.Scale(var2, var3, num1)).to.equal(500)
		end)

		it("survives a profile with no Entitlements field", function()
			local tbl1 = {}
			local var2 = var1.X2Money
			local num1 = 250
			expect(var1.Scale(tbl1, var2, num1)).to.equal(250)
		end)

		it("adds every owned storage bonus", function()
			local var3 = var2.FishStorage.BaseCapacity
			expect(var1.FishCapacity(withKeys())).to.equal(var3)
			local var4 = var1.X2FishInventory
			expect(var1.FishCapacity(withKeys(var4))).to.equal(var3 + 50)
			var4 = var1.X3FishInventory
			expect(var1.FishCapacity(withKeys(var4))).to.equal(var3 + 100)
			var4 = var1.X2FishInventory
			local var5 = var1.X3FishInventory
			expect(var1.FishCapacity(withKeys(var4, var5))).to.equal(var3 + 150)
		end)

		it("scales every key it names a multiplier for", function()
			for k1, v1 in var1.Multipliers, nil do
				local var2 = withKeys(k1)
				local var3 = k1
				local num1 = 10
				local var4 = expect(var1.Scale(var2, var3, num1)).to.equal
				var4(10 * v1)
			end
		end)
	end)
end

