	SkinTheme = "Dragon",
	Currency = "Gem",
	Prices = tbl2,
}

local tbl5 = { RodSkinId = "dragon_claw_rod", Weight = 1 }
local tbl6 = { RodSkinId = "dragon_rod", Weight = 1 }
tbl3.Pool = {
	{ RodSkinId = "dragon_wing_rod", Weight = 50 },
	{ RodSkinId = "dragon_bone_rod", Weight = 24 },
	{ RodSkinId = "dragon_sword_rod", Weight = 24 },
	tbl5,
	tbl6,
}

tbl3.Pity = { Threshold = 150, MinimumRarity = "Mythical" }
tbl4.crate_dragon_chest = tbl3
tbl3 = {}
tbl2 = {}
for k1, v1 in tbl4, nil do
	assert(#v1.Pool == 5, (("[CrateConfig] %* must contain exactly five RodSkins"):format(k1)))
	local num1 = 0
	local tbl7 = {}
	local tbl8 = {}
	for k2, v2 in v1.Pool, nil do
		assert(0 < v2.Weight, (("[CrateConfig] %*/%* must have a positive weight"):format(k1, v2.RodSkinId)))
		assert(not tbl8[v2.RodSkinId], (("[CrateConfig] %* contains duplicate RodSkin %*"):format(k1, v2.RodSkinId)))
		assert(var1.RodSkin.GetById(v2.RodSkinId) ~= nil, (("[CrateConfig] %* references unknown RodSkin %*"):format(k1, v2.RodSkinId)))
		tbl8[v2.RodSkinId] = true
		tbl7[v2.RodSkinId] = v2.Weight
		local var2 = v2.Weight
		num1 = num1 + var2
	end

	assert(0 < num1, (("[CrateConfig] %* must have a positive total weight"):format(k1)))
	tbl3[k1] = {
		Id = v1.Id,
		DisplayName = v1.DisplayName,
		SkinTheme = v1.SkinTheme,
		Currency = v1.Currency,
		Prices = v1.Prices,
		Pool = v1.Pool,
		Weights = tbl7,
		TotalWeight = num1,
		Pity = v1.Pity,
	}

	local var3 = table.create(#v1.Pool)
	for k3, v3 in v1.Pool, nil do
		local var4 = var1.RodSkin.GetById(v3.RodSkinId)
		assert(var4 ~= nil, (("[CrateConfig] Missing validated RodSkin %*"):format(v3.RodSkinId)))
		table.insert(var3, {
			RodSkinId = v3.RodSkinId,
			Weight = v3.Weight,
			Rate = v3.Weight / num1 * 100,
			Item = var4,
		})

	end

	tbl2[k1] = var3
end

