local var1 = require(script.Parent.CrateConfig)
local var2 = require(game:GetService("ReplicatedStorage").Data.Catalog)
return function()
	describe("CrateConfig", function()
		it("defines the two canonical crate ids and prices", function()
			expect(#var1.CrateIds).to.equal(2)
			local str1 = "crate_ocean_chest"
			local num1 = 1
			expect(var1.GetPrice(str1, num1)).to.equal(500000)
			str1 = "crate_ocean_chest"
			num1 = 10
			expect(var1.GetPrice(str1, num1)).to.equal(5000000)
			str1 = "crate_dragon_chest"
			num1 = 1
			expect(var1.GetPrice(str1, num1)).to.equal(200)
			str1 = "crate_dragon_chest"
			num1 = 10
			expect(var1.GetPrice(str1, num1)).to.equal(2000)
			local var2 = var1.GetCrate("crate_ocean_chest")
			num1 = var2
			str1 = expect(num1 and var2.Currency).to.equal
			str1("Coin")
			local var3 = var1.GetCrate("crate_dragon_chest")
			num1 = var3
			str1 = expect(num1 and var3.Currency).to.equal
			str1("Gem")
			num1 = var2
			str1 = expect(num1 and var2.SkinTheme).to.equal
			str1("Ocean")
			num1 = var3
			str1 = expect(num1 and var3.SkinTheme).to.equal
			str1("Dragon")
			local str2 = "Ocean_Chest"
			expect(var1.GetCrate(str2)).to.equal(nil)
		end)

		it("uses the approved ordered pool rates and Mythical pity", function()
			local tbl1 = { "dragon_sword_rod", 24 }
			local tbl2 = { "dragon_claw_rod", 1 }
			for k1, v1 in {
				crate_ocean_chest = {
					{ "jellyfish_rod", 40 },
					{ "shark_rod", 35 },
					{ "abyssal_mast", 12.45 },
					{ "ocean_scythe_rod", 12.45 },
					{ "taiji_trident", 0.1 },
				},
				crate_dragon_chest = { { "dragon_wing_rod", 50 }, { "dragon_bone_rod", 24 }, tbl1, tbl2, { "dragon_rod", 1 } },
			}, nil do

				local var2 = var1.GetPool(k1)
				expect(var2).never.to.equal(nil)
				if not var2 then
					return
				end

				for k2, v2 in v1, nil do
					expect(var2[k2].RodSkinId).to.equal(v2[1])
					expect(var2[k2].Rate).to.equal(v2[2])
				end
			end

			local var3 = var1.GetCrate("crate_ocean_chest")
			expect(var3).never.to.equal(nil)
			local var4 = var1.GetCrate("crate_dragon_chest")
			expect(var4).never.to.equal(nil)
			if not var3 or (not var4) then
				return
			end

			expect(var3.Pity.Threshold).to.equal(1000)
			expect(var4.Pity.Threshold).to.equal(150)
		end)

		for k1, v1 in var1.CrateIds, nil do
			it(("defines five valid RodSkins totaling 100 weight for %*"):format(v1), function()
				local var3 = var1.GetCrate(v1)
				expect(var3).never.to.equal(nil)
				local var4 = var1.GetPool(v1)
				expect(var4).never.to.equal(nil)
				if not var3 or (not var4) then
					return
				end

				expect(#var4).to.equal(5)
				expect(var3.TotalWeight).to.equal(100)
				local num1 = 0
				for k1, v2 in var4, nil do
					local var5 = v2.RodSkinId
					expect(var2.RodSkin.GetById(var5)).never.to.equal(nil)
					num1 = num1 + v2.Rate
				end

				expect(num1).to.equal(100)
			end)

		end
	end)
end

