--- ReplicatedStorage.Data.Config.RodAnimationConfig.spec [ModuleScript]
-- y u r i

return function()
	local var1 = require(game:GetService("ReplicatedStorage").Data.Config.RodAnimationConfig)
	local var2 = require(game:GetService("ReplicatedFirst").manual_assets)
	describe("RodAnimationConfig", function()
		it("resolves the base rod default when the skin has no override", function()
			local var3 = var1.Resolve("RodIdle", nil)
			expect(var3).to.be.ok()
			expect(var3.id).to.equal(var2["Animation/Rod/Idle"])
			expect(var3.priority).to.equal(Enum.AnimationPriority.Action)
			expect(var3.looped).to.equal(true)
			expect(var3.fadeTime).to.equal(0.15)
			expect(var3.playbackSpeed).to.equal(1)
			expect(var3.overlay).to.equal(false)
		end)

		it("a bare-string skin override wins over the default id", function()
			local var2 = var1.Resolve("RodIdle", { Idle = "rbxassetid://999" })
			expect(var2).to.be.ok()
			expect(var2.id).to.equal("rbxassetid://999")
			expect(var2.fadeTime).to.equal(0.15)
			expect(var2.playbackSpeed).to.equal(1)
		end)

		it("a table skin override applies playback_speed/fade_time and leaves unlisted fields at the def", function()
			local var2 = var1.Resolve("RodThrow", { Throw = { id = "rbxassetid://999", playback_speed = 1.5, fade_time = 0.1 } })
			expect(var2).to.be.ok()
			expect(var2.id).to.equal("rbxassetid://999")
			expect(var2.playbackSpeed).to.equal(1.5)
			expect(var2.fadeTime).to.equal(0.1)
			expect(var2.priority).to.equal(Enum.AnimationPriority.Action2)
			expect(var2.looped).to.equal(false)
		end)

		it("a table override with only fade_time keeps the def playback_speed", function()
			local var2 = var1.Resolve("RodCastLoop", { CastLoop = { id = "rbxassetid://999", fade_time = 0.5 } })
			expect(var2).to.be.ok()
			expect(var2.fadeTime).to.equal(0.5)
			expect(var2.playbackSpeed).to.equal(1)
		end)

		it("falls back to the default id when the skin's override id is empty", function()
			local var3 = var1.Resolve("RodIdle", { Idle = "" })
			expect(var3).to.be.ok()
			expect(var3.id).to.equal(var2["Animation/Rod/Idle"])
		end)

		it("returns nil when neither the skin nor the default has an id", function()
			expect((var1.Resolve("RodIdleArmsOnly", nil))).to.equal(nil)
		end)

		it("returns nil for an unknown track name", function()
			local str1 = "NotATrack"
			local var2 = nil
			expect(var1.Resolve(str1, var2)).to.equal(nil)
		end)

		it("marks the QTE counters as overlay and every other track as non-overlay", function()
			local tbl1 = { RodCounterLeft = true, RodCounterRight = true, RodCounterUp = true }
			for k1, v1 in var1.Defs, nil do
				expect(v1.overlay).to.equal(tbl1[k1] == true)
			end
		end)

		it("every def's tag has a matching Animation/Rod/<tag> key in manual_assets", function()
			for k1, v1 in var1.Defs, nil do
				local var3 = ("Animation/Rod/%*"):format(v1.tag)
				expect(var2[var3]).never.to.equal(nil)
				expect((type(var2[var3]))).to.equal("string")
				_ = k1
			end
		end)
	end)
end

