	RequiresConfirm = { Legendary = true, Mythical = true, Divine = true },
	SettingId = function(arg1)
		local var1 = tbl2[arg1]
		return var1 or "auto_sell_" .. string.lower(arg1)
	end,
	LayoutOrder = function(arg1)
		if arg1 == "Huge" then
			return -1
		end

		local var1 = table.find(var2.Order, arg1)
		return var1 or #var2.Order + 1
	end,
	BuildOptions = function(arg1)
		local var1 = arg1
		local tbl3 = {}
		var1 = var1 and arg1.Settings
		for k1, v1 in tbl1, nil do
			local var2 = (if type(var1) == "table" then var1[tbl2[v1]] else nil) == true
			tbl3[v1] = var2
		end

		return tbl3
	end,
}

