	local var2 = require(var1.Data.Config.SettingsConfig)
	local function eachSetting(arg1)
		for k1, v1 in var2.Settings, nil do
			for k2, v2 in v1, nil do
				arg1(k1, v2)
			end
		end
	end

	local var3 = require(var1.Data.Config.AutoSellConfig)
	describe("SettingsConfig", function()
		it("gives every setting a unique snake_case id", function()
			local tbl1 = {}
			eachSetting(function(_, arg2)
				expect(string.match(arg2.Id, "^[a-z][a-z0-9_]*$") ~= nil).to.equal(true)
				expect(tbl1[arg2.Id]).to.equal(nil)
				tbl1[arg2.Id] = true
			end)
		end)

		it("gives every setting a label, a known type and a default of that type", function()
			eachSetting(function(_, arg2)
				local var1 = expect
				local bool1 = false
				if type(arg2.Label) == "string" then
					bool1 = 0 < (#arg2.Label)
				end

				var1 = var1(bool1).to.equal
				var1(true)
				if arg2.Type == "boolean" then
					expect((type(arg2.Default))).to.equal("boolean")
					return
				end

				if arg2.Type == "volume" then
					expect((type(arg2.Default))).to.equal("number")
					var1 = expect
					bool1 = false
					if 0 <= arg2.Default then
						bool1 = arg2.Default <= 100
					end

					var1 = var1(bool1).to.equal
					var1(true)
					return
				end

				error((("%* has an unknown type %*"):format(arg2.Id, (tostring(arg2.Type)))))
			end)
		end)

		it("only orders and places premade frames in categories that exist", function()
			for k1, v1 in var2.Order, nil do
				expect(var2.Settings[v1] ~= nil).to.equal(true)
			end

			for k2 in var2.Premade, nil do
				expect(var2.Settings[k2] ~= nil).to.equal(true)
			end
		end)

		it("resolves each setting by its id", function()
			eachSetting(function(arg1, arg2)
				local var1, var3 = var2.getSetting(arg2.Id)
				expect(var1).to.equal(arg1)
				expect(var3).to.equal(arg2)
			end)
		end)

		it("treats an unknown id as a plain miss for getSetting", function()
			local var1, var3 = var2.getSetting("no_such_setting")
			expect(var1).to.equal(nil)
			expect(var3).to.equal(nil)
		end)

		it("reads the stored value and falls back to the default", function()
			local var1 = nil
			local str1 = "show_damage_indicator"
			expect(var2.read(var1, str1)).to.equal(true)
			var1 = {}
			str1 = "show_damage_indicator"
			expect(var2.read(var1, str1)).to.equal(true)
			var1 = { show_damage_indicator = false }
			str1 = "show_damage_indicator"
			expect(var2.read(var1, str1)).to.equal(false)
		end)

		it("keeps a stored zero volume instead of falling back to the default", function()
			local tbl1 = { master_volume = 0 }
			local str1 = "master_volume"
			expect(var2.read(tbl1, str1)).to.equal(0)
		end)

		it("throws on an unknown id when read in Studio", function()
			expect(function()
				var2.read({}, "no_such_setting")
			end).to.throw()
		end)

		it("registers an id for every auto-sell option", function()
			for k1, v1 in var3.Order, nil do
				local var1 = v1
				expect(var2.getSetting(var3.SettingId(var1)) ~= nil).to.equal(true)
			end
		end)
	end)
end

