--- ReplicatedStorage.Utils.NumberFormat.spec [ModuleScript]
-- y u r i

return function()
	local var1 = require(script.Parent.NumberFormat)
	describe("FormatCompact", function()
		it("keeps integer values below one thousand un-compacted", function()
			local num1 = 0
			expect(var1.FormatCompact(num1)).to.equal("0")
			num1 = 999
			expect(var1.FormatCompact(num1)).to.equal("999")
			num1 = 999.9
			expect(var1.FormatCompact(num1)).to.equal("999")
		end)

		it("compacts with two truncated decimals and trims zeroes", function()
			local num1 = 1000
			expect(var1.FormatCompact(num1)).to.equal("1K")
			num1 = 1200
			expect(var1.FormatCompact(num1)).to.equal("1.2K")
			num1 = 1239
			expect(var1.FormatCompact(num1)).to.equal("1.23K")
			num1 = 1299
			expect(var1.FormatCompact(num1)).to.equal("1.29K")
			num1 = 999999
			expect(var1.FormatCompact(num1)).to.equal("999.99K")
			num1 = 1000000
			expect(var1.FormatCompact(num1)).to.equal("1M")
		end)

		it("supports negative debug values", function()
			local num1 = -999
			expect(var1.FormatCompact(num1)).to.equal("-999")
			num1 = -1239
			expect(var1.FormatCompact(num1)).to.equal("-1.23K")
		end)

		it("displays bad numbers for debugging", function()
			local num1 = 0/0
			expect(var1.FormatCompact(num1)).to.equal("NaN")
			num1 = math.huge
			expect(var1.FormatCompact(num1)).to.equal("Infinity")
			num1 = -math.huge
			expect(var1.FormatCompact(num1)).to.equal("-Infinity")
		end)
	end)

	describe("FormatCompactFixed", function()
		it("keeps two decimals for leaderboard-style compact values", function()
			local num1 = 9000
			expect(var1.FormatCompactFixed(num1)).to.equal("9.00K")
			num1 = 1234
			expect(var1.FormatCompactFixed(num1)).to.equal("1.23K")
			num1 = 999
			expect(var1.FormatCompactFixed(num1)).to.equal("999.00")
		end)
	end)

	describe("FormatDecimal", function()
		it("keeps the real magnitude instead of compacting", function()
			local num1 = 1284.36
			expect(var1.FormatDecimal(num1)).to.equal("1284.36")
			num1 = 1000000
			expect(var1.FormatDecimal(num1)).to.equal("1000000")
		end)

		it("rounds to two decimals and trims zeroes", function()
			local num1 = 19
			expect(var1.FormatDecimal(num1)).to.equal("19")
			num1 = 4.5
			expect(var1.FormatDecimal(num1)).to.equal("4.5")
			num1 = 4.5
			expect(var1.FormatDecimal(num1)).to.equal("4.5")
			num1 = 1284.3600000000001
			expect(var1.FormatDecimal(num1)).to.equal("1284.36")
			num1 = 0.759
			expect(var1.FormatDecimal(num1)).to.equal("0.76")
		end)

		it("does not lose a cent the way the compact path's truncation does", function()
			local num1 = 1284.36
			expect(var1.FormatDecimal(num1)).to.equal("1284.36")
			num1 = 8.7
			expect(var1.FormatDecimal(num1)).to.equal("8.7")
		end)

		it("supports negative debug values", function()
			local num1 = -4.5
			expect(var1.FormatDecimal(num1)).to.equal("-4.5")
			num1 = -1284.36
			expect(var1.FormatDecimal(num1)).to.equal("-1284.36")
		end)

		it("displays bad numbers for debugging", function()
			local num1 = 0/0
			expect(var1.FormatDecimal(num1)).to.equal("NaN")
			num1 = math.huge
			expect(var1.FormatDecimal(num1)).to.equal("Infinity")
			num1 = -math.huge
			expect(var1.FormatDecimal(num1)).to.equal("-Infinity")
		end)
	end)

	describe("FormatGrouped", function()
		it("groups integers with commas", function()
			local num1 = 999
			expect(var1.FormatGrouped(num1)).to.equal("999")
			num1 = 1234567
			expect(var1.FormatGrouped(num1)).to.equal("1,234,567")
			num1 = 1234567.9
			expect(var1.FormatGrouped(num1)).to.equal("1,234,567")
		end)

		it("supports negative debug values", function()
			local num1 = -999
			expect(var1.FormatGrouped(num1)).to.equal("-999")
			num1 = -1234567
			expect(var1.FormatGrouped(num1)).to.equal("-1,234,567")
		end)

		it("displays bad numbers for debugging", function()
			local num1 = 0/0
			expect(var1.FormatGrouped(num1)).to.equal("NaN")
			num1 = math.huge
			expect(var1.FormatGrouped(num1)).to.equal("Infinity")
			num1 = -math.huge
			expect(var1.FormatGrouped(num1)).to.equal("-Infinity")
		end)
	end)
end

