			expect(var2.Transcendent).to.equal(1)
			expect(var2.Mythical).to.equal(2)
			expect(var2.Common).to.equal(3)
			local tbl1 = {
				{ key = "mythical", name = "A", rarity = "Mythical" },
				{ key = "new", name = "Z", rarity = "Transcendent" },
				{ key = "common", name = "B", rarity = "Common" },
			}

			var1.Sort(tbl1, var2)
			expect(tbl1[1].key).to.equal("new")
			expect(tbl1[2].key).to.equal("mythical")
		end)

		it("ties by display text then stable key", function()
			local tbl1 = {
				{ key = "b", name = "Same" },
				{ key = "c", name = "Alpha" },
				{ key = "a", name = "Same" },
			}

			var1.Sort(tbl1, {})
			expect(tbl1[1].key).to.equal("c")
			expect(tbl1[2].key).to.equal("a")
			expect(tbl1[3].key).to.equal("b")
		end)

		it("diffs add update remove and only requests sort for membership or sort changes", function()
			local tbl1 = {
				a = { fingerprint = "1", sortKey = "Common:A:a" },
				b = { fingerprint = "1", sortKey = "Rare:B:b" },
			}

			local tbl2 = {
				b = { fingerprint = "2", sortKey = "Rare:B:b" },
				c = { fingerprint = "1", sortKey = "Epic:C:c" },
			}

			local var2 = var1.Diff(tbl1, tbl2)
			expect(var2.added[1]).to.equal("c")
			expect(var2.updated[1]).to.equal("b")
			expect(var2.removed[1]).to.equal("a")
			expect(var2.requiresSort).to.equal(true)
			expect(var1.Diff({ b = tbl1.b }, { b = tbl2.b }).requiresSort).to.equal(false)
			local var3 = var1.Diff({ b = { fingerprint = "1", sortKey = "Rare:B:b" } }, { b = { fingerprint = "1", sortKey = "Rare:A:b" } })
			expect(var3.updated[1]).to.equal("b")
			expect(var3.requiresSort).to.equal(true)
		end)

		it("coalesces repeated dirty marks and defers uninitialized categories", function()
			local tbl1 = { initialized = true, initializing = false, dirty = false, scheduled = false }
			local var2 = tbl1
			expect(var1.MarkDirty(var2)).to.equal(true)
			var2 = tbl1
			expect(var1.MarkDirty(var2)).to.equal(false)
			expect(tbl1.dirty).to.equal(true)
			local tbl2 = { initialized = false, initializing = false, dirty = false, scheduled = false }
			local var3 = tbl2
			expect(var1.MarkDirty(var3)).to.equal(false)
			expect(tbl2.dirty).to.equal(true)
		end)

		it("keeps selection, then falls back to equipped, then clears", function()
			local tbl1 = { a = true, b = true }
			local str1 = "a"
			local var2 = tbl1
			local str2 = "b"
			expect(var1.ResolveSelection(str1, var2, str2)).to.equal("a")
			str1 = "missing"
			var2 = tbl1
			str2 = "b"
			expect(var1.ResolveSelection(str1, var2, str2)).to.equal("b")
			str1 = "missing"
			var2 = tbl1
			str2 = "missing"
			expect(var1.ResolveSelection(str1, var2, str2)).to.equal(nil)
		end)
	end)
end

