			local var3 = if arg2.rarity then arg2[arg2.rarity] or math.huge else math.huge
			if var1 ~= var3 then
				return var1 < var3
			end

			local var6 = string.lower(arg1.name)
			local var7 = string.lower(arg2.name)
			if var6 ~= var7 then
				return var6 < var7
			end

			return arg1.key < arg2.key
		end)
	end,
	Diff = function(arg1, arg2)
