					table.insert(tbl1.updated, k1)
					if var2.sortKey == v1.sortKey then
						continue
					end

					tbl1.requiresSort = true
				end
			end
		end

		for k2 in arg1, nil do
			if arg2[k2] then
				continue
			end

			table.insert(tbl1.removed, k2)
			tbl1.requiresSort = true
		end

		table.sort(tbl1.added)
		table.sort(tbl1.updated)
		table.sort(tbl1.removed)
		return tbl1
	end,
	MarkDirty = function(arg1)
		arg1.dirty = true
		if not arg1.initialized or (arg1.initializing or arg1.scheduled) then
			return false
		end

		arg1.scheduled = true
		return true
	end,
	ResolveSelection = function(arg1, arg2, arg3)
		if arg1 and arg2[arg1] then
			return arg1
		end

		if arg3 and arg2[arg3] then
			return arg3
		end

		return nil
	end,
}

