--- ReplicatedStorage.Utils.EventDisplayUtil.spec [ModuleScript]
-- y u r i

return function()
	local var1 = require(script.Parent.EventDisplayUtil)
	describe("FormatPercent", function()
		it("formats whole percentages without decimals", function()
			local num1 = 0
			expect(var1.FormatPercent(num1)).to.equal("+0%")
			num1 = 0.1
			expect(var1.FormatPercent(num1)).to.equal("+10%")
			num1 = 1
			expect(var1.FormatPercent(num1)).to.equal("+100%")
		end)

		it("absorbs float drift from repeated per-friend addition", function()
			local num1 = 0.06
			expect(var1.FormatPercent(num1)).to.equal("+6%")
			num1 = 0.1
			expect(var1.FormatPercent(num1)).to.equal("+10%")
		end)

		it("keeps significant decimals and trims trailing zeroes", function()
			local num1 = 0.075
			expect(var1.FormatPercent(num1)).to.equal("+7.5%")
			num1 = 0.125
			expect(var1.FormatPercent(num1)).to.equal("+12.5%")
		end)

		it("uses a minus sign instead of a plus for negative ratios", function()
			local num1 = -0.05
			expect(var1.FormatPercent(num1)).to.equal("-5%")
		end)

		it("falls back to zero for non-finite input", function()
			local num1 = 0/0
			expect(var1.FormatPercent(num1)).to.equal("+0%")
			num1 = math.huge
			expect(var1.FormatPercent(num1)).to.equal("+0%")
		end)
	end)

	describe("FormatTimer", function()
		it("zero-pads all three groups below one hour", function()
			local num1 = 45
			expect(var1.FormatTimer(num1)).to.equal("00:00:45")
			num1 = 90
			expect(var1.FormatTimer(num1)).to.equal("00:01:30")
			num1 = 3599
			expect(var1.FormatTimer(num1)).to.equal("00:59:59")
		end)

		it("formats hour boundaries", function()
			local num1 = 3600
			expect(var1.FormatTimer(num1)).to.equal("01:00:00")
			num1 = 3661
			expect(var1.FormatTimer(num1)).to.equal("01:01:01")
		end)

		it("lets hours overflow past two digits", function()
			local num1 = 360000
			expect(var1.FormatTimer(num1)).to.equal("100:00:00")
			num1 = 36000000
			expect(var1.FormatTimer(num1)).to.equal("10000:00:00")
		end)

		it("truncates fractional seconds", function()
			local num1 = 90.9
			expect(var1.FormatTimer(num1)).to.equal("00:01:30")
		end)

		it("reads zero for non-positive and non-finite input", function()
			local num1 = 0
			expect(var1.FormatTimer(num1)).to.equal("00:00:00")
			num1 = -5
			expect(var1.FormatTimer(num1)).to.equal("00:00:00")
			num1 = 0/0
			expect(var1.FormatTimer(num1)).to.equal("00:00:00")
		end)
	end)
end

