			phases = {
				{ id = "Started", pendingLabel = "Starting up..." },
				{ id = "Ui", pendingLabel = "Building interface..." },
				{ id = "Data", pendingLabel = "Loading your data..." },
				{ id = "Input", pendingLabel = "Preparing gameplay..." },
			},
			doneLabel = "Almost ready!",
			minDisplaySeconds = 3,
			timeoutSeconds = 120,
			nearFullProgress = 0.9,
			hintAfterSeconds = 5,
			hintPhaseId = "Data",
		}

		return var1.new(tbl1)
	end

	describe("LoadingPhases.Complete", function()
		it("counts a phase once however often it completes", function()
			local var1 = newTracker()
			var1:Complete("Ui")
			var1:Complete("Ui")
			expect(var1:CompletedCount()).to.equal(1)
		end)

		it("rejects an unknown phase id", function()
			local var1 = newTracker()
			expect(function()
				var1:Complete("Nope")
			end).to.throw()
		end)
	end)

	describe("LoadingPhases.Progress", function()
		it("is the completed share of the phases", function()
			local var1 = newTracker()
			var1:Complete("Started")
			local num1 = 10
			expect(var1:Progress(num1)).to.equal(0.25)
		end)

		it("holds at nearFullProgress until the minimum display time has passed", function()
			local var1 = newTracker()
			var1:Complete("Started")
			var1:Complete("Ui")
			var1:Complete("Data")
			var1:Complete("Input")
			local num1 = 1
			expect(var1:Progress(num1)).to.equal(0.9)
			num1 = 3
			expect(var1:Progress(num1)).to.equal(1)
		end)

		it("does not lift a ratio that is already under nearFullProgress", function()
			local var1 = newTracker()
			var1:Complete("Started")
			local num1 = 0
			expect(var1:Progress(num1)).to.equal(0.25)
		end)
	end)

	describe("LoadingPhases.Label", function()
		it("names the first pending phase in list order", function()
			local var1 = newTracker()
			local num1 = 0
			expect(var1:Label(num1)).to.equal("Starting up...")
			var1:Complete("Started")
			num1 = 0
			expect(var1:Label(num1)).to.equal("Building interface...")
		end)

		it("keeps naming the earlier pending phase when a later one finished first", function()
			local var1 = newTracker()
			var1:Complete("Started")
			var1:Complete("Ui")
			var1:Complete("Input")
			local num1 = 0
			expect(var1:Label(num1)).to.equal("Loading your data...")
		end)

		it("adds the elapsed hint to the hint phase only after hintAfterSeconds", function()
			local var1 = newTracker()
			var1:Complete("Started")
			var1:Complete("Ui")
			local num1 = 4.9
			expect(var1:Label(num1)).to.equal("Loading your data...")
			num1 = 7.6
			expect(var1:Label(num1)).to.equal("Loading your data...  (7s)")
		end)

		it("never adds the hint to a phase other than the hint phase", function()
			local num1 = 60
			expect(newTracker():Label(num1)).to.equal("Starting up...")
		end)

		it("shows the done label once every phase finished", function()
			local var1 = newTracker()
			var1:Complete("Started")
			var1:Complete("Ui")
			var1:Complete("Data")
			var1:Complete("Input")
			local num1 = 1
			expect(var1:Label(num1)).to.equal("Almost ready!")
		end)
	end)

	describe("LoadingPhases.Evaluate", function()
		it("waits while a phase is still pending", function()
			local var1 = newTracker()
			var1:Complete("Started")
			local num1 = 10
			expect(var1:Evaluate(num1)).to.equal(nil)
		end)

		it("waits for the minimum display time even when every phase finished", function()
			local var1 = newTracker()
			var1:Complete("Started")
			var1:Complete("Ui")
			var1:Complete("Data")
			var1:Complete("Input")
			local num1 = 2.9
			expect(var1:Evaluate(num1)).to.equal(nil)
			num1 = 3
			expect(var1:Evaluate(num1)).to.equal("Ready")
		end)

		it("times out with a phase still pending", function()
			local var1 = newTracker()
			var1:Complete("Started")
			local num1 = 119.9
			expect(var1:Evaluate(num1)).to.equal(nil)
			num1 = 120
			expect(var1:Evaluate(num1)).to.equal("Timeout")
		end)

		it("prefers Ready over Timeout when everything finished by the deadline", function()
			local var1 = newTracker()
			var1:Complete("Started")
			var1:Complete("Ui")
			var1:Complete("Data")
			var1:Complete("Input")
			local num1 = 500
			expect(var1:Evaluate(num1)).to.equal("Ready")
		end)

		it("returns a verdict once, so a racing timer cannot dismiss the screen twice", function()
			local var1 = newTracker()
			var1:Complete("Started")
			var1:Complete("Ui")
			var1:Complete("Data")
			var1:Complete("Input")
			expect(var1:IsFinished()).to.equal(false)
			local num1 = 3
			expect(var1:Evaluate(num1)).to.equal("Ready")
			expect(var1:IsFinished()).to.equal(true)
			num1 = 3
			expect(var1:Evaluate(num1)).to.equal(nil)
			num1 = 200
			expect(var1:Evaluate(num1)).to.equal(nil)
		end)
	end)

	describe("LoadingPhases.new", function()
		it("rejects a minimum display time longer than the timeout", function()
			expect(function()
				var1.new({
					phases = { { id = "A", pendingLabel = "A" } },
					doneLabel = "Done",
					minDisplaySeconds = 10,
					timeoutSeconds = 5,
					nearFullProgress = 0.9,
					hintAfterSeconds = 1,
					hintPhaseId = "A",
				})
			end).to.throw()
		end)

		it("rejects a hint phase that is not in the phase list", function()
			expect(function()
				var1.new({
					phases = { { id = "A", pendingLabel = "A" } },
					doneLabel = "Done",
					minDisplaySeconds = 1,
					timeoutSeconds = 5,
					nearFullProgress = 0.9,
					hintAfterSeconds = 1,
					hintPhaseId = "B",
				})
			end).to.throw()
		end)
	end)
end

