--- ReplicatedStorage.Shared.Lib.DailyRewardUtil.spec [ModuleScript]
-- y u r i

return function()
	local var1 = require(script.Parent.DailyRewardUtil)
	describe("compute_state", function()
		it("offers day 1 to a brand-new player", function()
			local var2 = var1.compute_state({ CycleStart = 0, Claimed = 0, LastClaim = 0 }, 1000)
			expect(var2.ClaimableDay).to.equal(1)
			expect(var2.Claimed).to.equal(0)
			expect(var2.Expired).to.equal(false)
			expect(var2.WaitingDay).to.equal(nil)
		end)

		it("offers the next sequential day exactly 24 hours after the previous claim", function()
			local var2 = var1.compute_state({ CycleStart = 432000000, Claimed = 3, LastClaim = 432172800 }, 432259200)
			expect(var2.ClaimableDay).to.equal(4)
			expect(var2.Expired).to.equal(false)
			expect(var2.WaitingDay).to.equal(nil)
		end)

		it("holds the next day for one second short of 24 hours", function()
			local var2 = var1.compute_state({ CycleStart = 432000000, Claimed = 3, LastClaim = 432172800 }, 432259199)
			expect(var2.ClaimableDay).to.equal(nil)
			expect(var2.WaitingDay).to.equal(4)
		end)

		it("blocks a second claim on the same day and shows the waiting day", function()
			local var2 = var1.compute_state({ CycleStart = 432000000, Claimed = 3, LastClaim = 432259200 }, 432259260)
			expect(var2.ClaimableDay).to.equal(nil)
			expect(var2.WaitingDay).to.equal(4)
			expect(var2.Expired).to.equal(false)
		end)

		it("expires by elapsed time and re-anchors a fresh day 1", function()
			local var2 = var1.compute_state({ CycleStart = 432000000, Claimed = 3, LastClaim = 432259200 }, 432691200)
			expect(var2.ClaimableDay).to.equal(1)
			expect(var2.Claimed).to.equal(0)
			expect(var2.Expired).to.equal(true)
		end)

		it("expires by count once all 7 are claimed", function()
			local var2 = var1.compute_state({ CycleStart = 432000000, Claimed = 7, LastClaim = 432432000 }, 432518400)
			expect(var2.ClaimableDay).to.equal(1)
			expect(var2.Claimed).to.equal(0)
			expect(var2.Expired).to.equal(true)
		end)

		it("is idempotent: re-running the same moment after a claim yields no claimable day", function()
			local var2 = var1.compute_state({ CycleStart = 432000000, Claimed = 1, LastClaim = 432000000 }, 432000000)
			expect(var2.ClaimableDay).to.equal(nil)
			expect(var2.WaitingDay).to.equal(2)
		end)

		it("shows no waiting day once the cycle is fully claimed", function()
			local var2 = var1.compute_state({ CycleStart = 432000000, Claimed = 7, LastClaim = 432518400 }, 432518400)
			expect(var2.ClaimableDay).to.equal(nil)
			expect(var2.WaitingDay).to.equal(nil)
		end)

		it("walks day 1..7 across consecutive 24-hour periods then recycles", function()
			local num1 = 0
			local num2 = 0
			local num3 = 0
			for i1 = 1, 7 do
				local var2 = (i1 - 1) * 86400 + 432000000
				expect(var1.compute_state({ CycleStart = num2, Claimed = num1, LastClaim = num3 }, var2).ClaimableDay).to.equal(i1)
				if num2 == 0 then
					num2 = var2
				end

				num1 = i1
				num3 = var2
			end

			local var3 = var1.compute_state({ CycleStart = num2, Claimed = num1, LastClaim = num3 }, 432604800)
			expect(var3.ClaimableDay).to.equal(1)
			expect(var3.Expired).to.equal(true)
		end)
	end)
end

