--- ReplicatedStorage.Shared.Lib.CratePresentationFlow [ModuleScript]
-- y u r i

local tbl1 = { Run = function(arg1, arg2, arg3, arg4, arg5)
	local bool1 = false
	local bool2 = false
	local function finish()
		if bool1 then
			return
		end

		bool1 = true
		arg1.finish()
	end

	local function reveal()
		if bool2 then
			return
		end

		bool2 = true
		if not pcall(arg1.reveal, arg2.results, arg3, finish) then
			arg1.warn("Loot reveal failed")
			if bool1 then
				return
			end

			bool1 = true
			arg1.finish()
		end
	end

	if not arg1.spinner then
		if bool2 then
		else
			bool2 = true
			if not pcall(arg1.reveal, arg2.results, arg3, finish) then
				arg1.warn("Loot reveal failed")
	if not bool1 then
					arg1.finish()
					bool1 = true
				end
			end
		end

		return
	end

	if not pcall(function()
		arg1.spinner:Play(arg4, reveal, arg5)
	end) then

		arg1.warn("Spinner failed")
		if bool2 then
		else
			if not pcall(arg1.reveal, arg2.results, arg3, finish) then
				arg1.warn("Loot reveal failed")
	if not bool1 then
					arg1.finish()
				end
			end
		end
	end
end }

return table.freeze(tbl1)

