--- ReplicatedStorage.Shared.Lib.FishingClickTiming [ModuleScript]
-- y u r i

local tbl1 = {
	StartAutomatic = function(arg1)
		return arg1
	end,
	StartAutomaticAfterInterval = function(arg1, arg2)
		assert(0 < arg2, "cps must be positive")
		return arg1 + 1 / arg2
	end,
	AdvanceAutomatic = function(arg1, arg2, arg3)
		assert(0 < arg3, "cps must be positive")
		local var1 = 1 / arg3
		local var3 = arg1 + var1
		if var3 <= arg2 then
			return arg2 + var1
		end

		return var3
	end,
	TryManual = function(arg1, arg2, arg3, arg4)
		assert(0 <= arg4, "tolerance must be non-negative")
		assert(0 < arg3, "cps must be positive")
		local var1 = 1 / arg3
		if arg1 and arg2 < arg1 - arg4 then
			return false, arg1
		end

		if arg1 and arg2 < arg1 then
			return true, arg1 + var1
		end

		return true, arg2 + var1
	end,
}

return table.freeze(tbl1)

