		it("leaves a value inside the range untouched and reports not-at-cap", function()
			local var2, var3 = var1.Clamp(0.5, 0, 0.8)
			expect(var2).to.equal(0.5)
			expect(var3).to.equal(false)
		end)

		it("clamps above the ceiling and reports at-cap", function()
			local var2, var3 = var1.Clamp(1.5, 0, 0.8)
			expect(var2).to.equal(0.8)
			expect(var3).to.equal(true)
		end)

		it("reports at-cap when the value lands exactly on the ceiling", function()
			local var2, var3 = var1.Clamp(0.8, 0, 0.8)
			expect(var2).to.equal(0.8)
			expect(var3).to.equal(true)
		end)

		it("clamps below the floor without reporting at-cap", function()
			local var2, var3 = var1.Clamp(-3, 0, 0.8)
			expect(var2).to.equal(0)
			expect(var3).to.equal(false)
		end)

		it("collapses NaN to the floor instead of propagating it", function()
