			expect(-var2).to.equal(-0.25)
			expect(var3).to.equal(true)
		end)
	end)

	describe("capUtil.Soft", function()
		it("returns zero for non-positive input", function()
			local num1 = 0
			local num2 = 40
			expect(var1.Soft(num1, num2)).to.equal(0)
			num1 = -5
			num2 = 40
			expect(var1.Soft(num1, num2)).to.equal(0)
		end)

		it("is linear below the soft cap", function()
			local num1 = 25
			local num2 = 40
			expect(var1.Soft(num1, num2)).to.equal(25)
			num1 = 40
			num2 = 40
			expect(var1.Soft(num1, num2)).to.equal(40)
		end)

		it("stays below twice the soft cap above it", function()
			local var2 = var1.Soft(1000000000, 40)
			expect(40 < var2).to.equal(true)
			expect(var2 < 80).to.equal(true)
		end)

		it("is monotonic across the cap boundary", function()
			local var2 = var1.Soft(40, 40)
			expect(var1.Soft(39, 40) < var2).to.equal(true)
			expect(var2 < var1.Soft(41, 40)).to.equal(true)
		end)
	end)
end

