-- y u r i

return function()
	local var1 = require(script.Parent)
	describe("Copy (Deep)", function()
		it("should create a deep table copy", function()
			local tbl1 = { a = { b = { c = { d = 32 } } } }
			local var2 = var1.Copy(tbl1, true)
			expect(tbl1).never.to.equal(var2)
			expect(tbl1.a).never.to.equal(var2.a)
			expect(var2.a.b.c.d).to.equal(tbl1.a.b.c.d)
		end)
	end)

	describe("Copy (Shallow)", function()
		it("should create a shallow dictionary copy", function()
			local tbl1 = { a = { b = { c = { d = 32 } } } }
			local var2 = var1.Copy(tbl1)
			expect(var2).never.to.equal(tbl1)
			expect(var2.a).to.equal(tbl1.a)
			expect(var2.a.b.c.d).to.equal(tbl1.a.b.c.d)
		end)

		it("should create a shallow array copy", function()
			local tbl1 = { 10, 20, 30, 40 }
			local var2 = var1.Copy(tbl1)
			expect(var2).never.to.equal(tbl1)
			for k1, v1 in ipairs(tbl1) do
				expect(var2[k1]).to.equal(v1)
			end
		end)
	end)

	describe("Sync", function()
		it("should sync tables", function()
			local tbl1 = { a = 32, b = 64, c = 128, e = { h = 1 } }
			local var2 = var1.Sync({ a = 32, b = 10, d = 1, e = { h = 2, n = 2 }, f = { x = 10 } }, tbl1)
			expect(var2.a).to.equal(tbl1.a)
			expect(var2.b).to.equal(10)
			expect(var2.c).to.equal(tbl1.c)
			expect(var2.d).never.to.be.ok()
			expect(var2.e.h).to.equal(2)
			expect(var2.e.n).never.to.be.ok()
			expect(var2.f).never.to.be.ok()
		end)
	end)

	describe("Reconcile", function()
		it("should reconcile table", function()
			local tbl1 = {
				kills = 10,
				deaths = 4,
				stuff = { "abc", "xyz" },
				extra = 5,
				stuff2 = { abc = 10 },
				stuff3 = true,
			}

			local tbl2 = { kills = 0, deaths = 0, xp = 10, stuff = {}, stuff2 = "abc", stuff3 = { "data" } }
			local var2 = var1.Reconcile(tbl1, tbl2)
			expect(var2).never.to.equal(tbl1)
			expect(var2).never.to.equal(tbl2)
			expect(var2.kills).to.equal(10)
			expect(var2.deaths).to.equal(4)
			expect(var2.xp).to.equal(10)
			expect(var2.stuff[1]).to.equal("abc")
			expect(var2.stuff[2]).to.equal("xyz")
			expect(var2.extra).to.equal(5)
			expect((type(var2.stuff2))).to.equal("table")
			expect(var2.stuff2).never.to.equal(tbl1.stuff2)
			expect(var2.stuff2.abc).to.equal(10)
			expect((type(var2.stuff3))).to.equal("boolean")
			expect(var2.stuff3).to.equal(true)
