		end)

		it("levels across multiple thresholds and keeps rolled bases unchanged", function()
			local var1 = var2.NewData()
			var2.Grant(var1, "u1", roll())
			var1.Owned.u1.Stats[1].BaseValue = 0.1
			local var3 = var1
			local str1 = "u1"
			local var4 = var2.RequiredExperience(1) + var2.RequiredExperience(2) + 7
			expect(var2.AddExperience(var3, str1, var4)).to.equal(true)
