			for k1, v1 in { -1, num1, 0.5, math.huge, 0/0 }, nil do
				local var3 = var1
				local str1 = "u1"
				local var4 = v1
				expect(var2.AddExperience(var3, str1, var4)).to.equal(false)
			end
		end)

		it("caps test level and discards XP after max level", function()
