			expect(var1.Owned.u1.Exp).to.equal(0)
			local var4 = var1
			local str1 = "u1"
			local num1 = 10
			expect(var2.AddExperience(var4, str1, num1)).to.equal(false)
		end)

		it("validates persistent ownership and equipped invariants", function()
			local var1 = var2.NewData()
			var2.Grant(var1, "u1", roll())
			var1.Equipped = { "u1", "u1" }
			local var3 = var1
			expect(var2.Validate(var3)).to.equal(false)
			var1.Capacity = 2
			var3 = var1
			expect(var2.Validate(var3)).to.equal(false)
			local tbl1 = {}
			tbl1[2] = "u1"
			var1.Equipped = tbl1
			var3 = var1
			expect(var2.Validate(var3)).to.equal(false)
			var1.Equipped = { "missing" }
			var3 = var1
			expect(var2.Validate(var3)).to.equal(false)
			var1.Equipped = { Slot1 = "u1" }
			var3 = var1
			expect(var2.Validate(var3)).to.equal(false)
		end)

		it("rejects malformed records and duplicate rolled stat keys", function()
			local var1 = var2.NewData()
			var2.Grant(var1, "u1", roll())
			var1.Owned.u1.Stats[2].Key = var1.Owned.u1.Stats[1].Key
			local var3 = var1
			expect(var2.Validate(var3)).to.equal(false)
			var1 = var2.NewData()
			var2.Grant(var1, "u1", roll())
			var1.Owned.u1.Age = math.huge
			var3 = var1
			expect(var2.Validate(var3)).to.equal(false)
			var1 = var2.NewData()
			var2.Grant(var1, "u1", roll())
			var1.Owned.u1.Stats[1].BaseValue = 0/0
			var3 = var1
			expect(var2.Validate(var3)).to.equal(false)
		end)

		it("preserves unknown saved unit types rather than invalidating the entire profile", function()
			local var1 = var2.NewData()
			var2.Grant(var1, "u1", roll())
			var1.Owned.u1.UnitId = "future_unit"
			local var3 = var1
			expect(var2.Validate(var3)).to.equal(true)
			var3 = var1
			local str1 = "u1"
			expect(var2.Equip(var3, str1)).to.equal(false)
		end)

		it("retains retired test records without granting or equipping them; supports explicit removal", function()
			local var1 = var2.NewData()
			var2.Grant(var1, "u1", roll())
			var1.Owned.u1.UnitId = "test_unit"
			var1.Equipped = { "u1" }
			local var3 = var1
			expect(var2.Validate(var3)).to.equal(true)
			local num1 = 1
			var3 = "test_unit"
			expect(var2.Roll(var3, Random.new(num1))).to.equal(nil)
			var3 = var1
			local str1 = "u1"
			expect(var2.Equip(var3, str1)).to.equal(false)
			var3 = var1
			str1 = "u1"
			expect(var2.Remove(var3, str1)).to.equal(true)
			var3 = var1.Owned
			expect(next(var3)).to.equal(nil)
			expect(#var1.Equipped).to.equal(0)
		end)

		it("only enlarges in fish combat, never cast/wait/result", function()
			local str1 = "Throwing"
			for k1, v1 in { "Holding", str1, "Waiting", "Caught", "Escaped", "Idling" }, nil do
				local var1 = v1
				expect(var2.IsCombatState(var1)).to.equal(false)
			end

			local str2 = "FirstPull"
			expect(var2.IsCombatState(str2)).to.equal(true)
			str2 = "Reeling"
			expect(var2.IsCombatState(str2)).to.equal(true)
		end)
	end)
end

--- ReplicatedStorage.Shared.Units.UnitRoll.spec [ModuleScript]
-- y u r i

local var1 = game:GetService("ReplicatedStorage")
local var2 = require(var1.Data.Catalog.Unit)
local var3 = require(script.Parent.UnitCore)
local var4 = require(var1.Data.Catalog.Skill)
local var5 = require(script.Parent.UnitConfig)
return function()
	local function controlled(arg1, arg2)
		return {
			NextNumber = function(_, arg2, arg3)
				return arg2 + (arg3 - arg2) * arg1
			end,
			NextInteger = function(_, arg2, arg3)
				if arg2 then
					return arg3
				end

				return arg2
			end,
		}
	end

	describe("Unit skill gacha helper", function()
		it("makes every book in every configured character pool reachable with one integer draw", function()
			for k1, v1 in var2, nil do
				local var1 = var3.GetSkillPool(k1)
				for k2, v2 in var1, nil do
					local num1 = 0
					local var5 = k1
					local tbl1 = {
						NextNumber = function()
							error("Skill gacha must not roll unit rarity or stats")
						end,
						NextInteger = function(_, arg2, arg3)
							local var2 = num1 + 1
							num1 = var2
							expect(arg2).to.equal(1)
							expect(arg3).to.equal(#var1)
							return k2
						end,
					}

					expect(var3.RollSkill(var5, tbl1)).to.equal(v2)
					expect(table.find(v1.skillGroups, var4[v2].group) ~= nil).to.equal(true)
					expect(num1).to.equal(1)
				end
			end
		end)

		it("returns nil for missing or unconfigured characters without consuming randomness", function()
			local str1 = "test_unit"
			local tbl1 = { NextInteger = function()
				error("Empty pools must not draw")
			end }

			for k1, v1 in { "missing", str1, "da_shixiong", "duan_gan", "hua_heshang" }, nil do
				local var1 = v1
				local var2 = tbl1
				expect(var3.RollSkill(var1, var2)).to.equal(nil)
			end
		end)

		it("does not restrict a character's skill pool to the unit's saved rarity", function()
			local num1 = 42
			local var1 = var3.Roll("xiao_daoshi", Random.new(num1))
			local var2 = var3.GetSkillPool(var1.UnitId)
			local var5 = table.find(var2, "hook_the_dragon")
			num1 = table.find(var2, "pure_yang_hooking_art")
			local var6 = expect
			local bool1 = false
			if var5 ~= nil then
				bool1 = num1 ~= nil
			end

			var6 = var6(bool1).to.equal
			var6(true)
			local str1 = "Legendary"
			for k1, v1 in { "Common", str1, "Mythical" }, nil do
				var1.Rarity = v1
				local var7 = num1
				for k2, v2 in { var5, var7 }, nil do
					local var8 = var1.UnitId
					local tbl1 = { NextInteger = function()
						return v2
					end }

					expect(var3.RollSkill(var8, tbl1)).to.equal(var2[v2])
				end
			end
		end)

		it("does not overwrite the owned unit, reroll its stats, or mutate a previously returned pool", function()
			local num1 = 42
			local var1 = var3.Roll("ba_chang", Random.new(num1))
			num1 = var3.GetSkillPool(var1.UnitId)
			table.clear(num1)
			local var2 = var1.UnitId
			local var4 = controlled(0, false)
			expect(var3.RollSkill(var2, var4)).to.equal(num1[1])
			local str1 = "Exp"
			local var5 = var3.CloneUnit(var1)
			local var6 = var1.Stats
			for k1, v1 in { "Age", str1, "Rarity", "ClickSpeed", "SkillDamageMultiplier", "SkillBookId" }, nil do
				expect(var1[v1]).to.equal(var5[v1])
			end

			expect(var1.Stats).to.equal(var6)
			for k2, v2 in var6, nil do
				expect(v2.Key).to.equal(var5.Stats[k2].Key)
				expect(v2.BaseValue).to.equal(var5.Stats[k2].BaseValue)
			end
		end)

		it("uses the same helper when creating a new unit", function()
			local num1 = 0
			local var1 = Random.new(42)
			var3.RollSkill = function(arg1, arg2)
				local var2 = num1 + 1
				num1 = var2
				expect(arg1).to.equal("ba_chang")
				expect(arg2).to.equal(var1)
				return "hook_the_dragon"
			end

			local success, result = pcall(var3.Roll, "ba_chang", var1)
			var3.RollSkill = var3.RollSkill
			if not success then
				error(result)
			end

			expect(result.SkillBookId).to.equal("hook_the_dragon")
			expect(num1).to.equal(1)
		end)
	end)

	describe("Unit character and independent rarity rolls", function()
		it("rolls each quality tier using its exact percentage and tenth-percent endpoint", function()
			local num1 = 0
			for k1, v1 in var5.BuffQualities, nil do
				local num2 = 0
				local var1 = (num1 + v1.Weight / 2) / 100
				local var2 = controlled(0, true)
				var2.NextNumber = function(_, arg2, arg3)
					local var2 = num2 + 1
					num2 = var2
					local var3 = arg3 - arg2
					return arg2 + var3 * (if num2 == 3 or num2 == 5 then var1 else 0)
				end

				local var4 = var3.Roll("ba_chang", var2)
				expect(var4.Stats[1].Key).to.equal("critDamage")
				expect(math.abs(var4.Stats[1].BaseValue - var5.BuffRolls[1].Ranges[k1][2] / 100) < 1e-09).to.equal(true)
				num1 = num1 + v1.Weight
			end

			expect(num1).to.equal(100)
		end)

		it("removes the first buff weight and normalizes the remaining pool for the second", function()
