		function(arg1)
			local var2 = arg1:GetArgument(1)
			local var4 = if var2 then var2:GetValue() else nil
			if var4 == nil then
				return nil
			end

			if var4 == "give" then
				return {
					Type = "positiveInteger",
					Name = "amount",
					Description = "How many fish to give. Each fish rolls its own weight.",
					Optional = true,
					Default = 1,
				}

			end

			return {
				Type = "players",
				Name = "players",
				Description = "Who to affect. Defaults to you.",
				Optional = true,
			}
		end,
		function(arg1)
			local var2 = arg1:GetArgument(1)
			if (if var2 then var2:GetValue() else nil) ~= "give" then
				return nil
			end

			return {
				Type = "fishHugeBoolean",
				Name = "huge",
				Description = "Force every given fish to roll as Huge.",
				Optional = true,
				Default = false,
			}
		end,
