--- ReplicatedStorage.CmdrClient.Commands.unit [ModuleScript]
-- y u r i

return {
	Name = "unit",
	Aliases = {},
	Description = "Manage units: add/remove/equip/unequip/capacity/xp/list/inspect/status. Equip needs no slot.",
	Group = "Admin",
	Args = {
		{ Type = "unitaction", Name = "action", Description = "Unit action" },
		function(arg1)
			local var2 = arg1:GetArgument(1)
			local var4 = if var2 then var2:GetValue() else nil
			if not var4 then
				return nil
			end

			if var4 == "list" or var4 == "status" then
				return {
					Type = "players",
					Name = "players",
					Description = "Who to affect. Defaults to you.",
					Optional = true,
				}

			end

			if var4 == "add" then
				return { Type = "unitId", Name = "unit", Description = "Unit type, 'random', or 'all'" }
			end

			if var4 == "capacity" then
				return {
					Type = "unitCapacity",
					Name = "capacity",
					Description = "Maximum number of equipped units",
				}

			end

			return {
				Type = "unitTarget",
				Name = "unit",
				Description = "UID from unit list, unit type, or 'all'",
			}
		end,
		function(arg1)
			local var2 = arg1:GetArgument(1)
			local var4 = if var2 then var2:GetValue() else nil
			if not var4 or (var4 == "list" or var4 == "status") then
				return nil
			end

			if var4 == "add" then
				return {
					Type = "positiveInteger",
					Name = "amount",
					Description = "Copies, each rolled separately (max 100)",
					Optional = true,
					Default = 1,
				}

			end

			if var4 == "xp" then
				return { Type = "positiveInteger", Name = "amount", Description = "XP to add to matching units" }
			end

			return {
				Type = "players",
				Name = "players",
				Description = "Who to affect. Defaults to you.",
				Optional = true,
			}
		end,
		function(arg1)
			local var2 = arg1:GetArgument(1)
