--- ReplicatedFirst.RemoveDefaultLoadingScreen [LocalScript]
-- y u r i

game:GetService("ReplicatedFirst"):RemoveDefaultLoadingScreen()
local var1 = game:GetService("GuiService")
pcall(function()
	var1:SetGameplayPausedNotificationEnabled(false)
end)

--- ReplicatedFirst.DisableAutoLocalization [LocalScript]
-- y u r i

local function disableOnGui(arg1)
	if arg1:IsA("LayerCollector") then
		arg1.AutoLocalize = false
	end
end

local function watch(arg1)
	if arg1:IsA("LayerCollector") then
		arg1.AutoLocalize = false
	end

	for k1, v1 in arg1:GetDescendants() do
		if not v1:IsA("LayerCollector") then
			continue
		end

		v1.AutoLocalize = false
	end

	arg1.DescendantAdded:Connect(disableOnGui)
end

watch((game:GetService("StarterGui")))
watch(workspace)
local str1 = "PlayerGui"
watch(game:GetService("Players").LocalPlayer:WaitForChild(str1))

